(function(){
'use strict';
// No network or filesystem dependency. Joplin owns note persistence.
const DotCore = (() => {
  const MAX_BODY = 180000;
  const JOURNAL_KEY = 'submissions.v1';
  const states = ['pending', 'disconnected', 'sending', 'unknown', 'failed', 'accepted'];
  const copy = value => JSON.parse(JSON.stringify(value));
  const same = (a, b) => a.title === b.title && a.body === b.body;
  function content(value) {
    if (!value || typeof value.title !== 'string' || typeof value.body !== 'string' ||
        value.title.length > 500 || value.body.length > MAX_BODY) {
      throw new Error('标题最多 500 字符，正文最多 180000 字符。内容未发送，请保留编辑区文字。');
    }
    return { title: value.title, body: value.body };
  }
  function id(value) {
    if (typeof value !== 'string' || !/^[a-f0-9]{32}$/.test(value)) throw new Error('笔记标识无效。');
    return value;
  }
  function journal(raw, noteId) {
    if (raw === undefined || raw === null) return { schema: 1, records: [] };
    if (!raw || raw.schema !== 1 || !Array.isArray(raw.records) || raw.records.length > 100) {
      throw new Error('发送记录格式异常；已停止操作，原记录未覆盖。');
    }
    raw.records.forEach((r, i) => {
      if (r.version !== i + 1 || r.key !== noteId + ':' + r.version || !states.includes(r.state) ||
          !Number.isSafeInteger(r.attempts) || r.attempts < 0) throw new Error('发送记录损坏；已停止操作。');
      content(r.snapshot);
    });
    return copy(raw);
  }
  const disconnected = Object.freeze({
    connected: false,
    async send() { throw new Error('未连接：尚未验证现有 dot 的接收通道。'); }
  });
  class Service {
    constructor(store, adapter = disconnected, timeoutMs = 10000) {
      this.store = store;
      this.adapter = adapter;
      this.timeoutMs = timeoutMs;
      this.tail = Promise.resolve();
    }
    // Serialize mutations so autosave, switching, and double-clicks cannot race.
    run(fn) {
      const result = this.tail.then(fn);
      this.tail = result.catch(() => {});
      return result;
    }
    async read(noteId) {
      const note = await this.store.read(id(noteId));
      content(note);
      const state = journal(await this.store.readJournal(noteId), noteId);
      return { note, journal: state, connected: this.adapter.connected === true };
    }
    async writeJournal(noteId, state) {
      await this.store.writeJournal(noteId, copy(state));
      const saved = journal(await this.store.readJournal(noteId), noteId);
      if (JSON.stringify(saved) !== JSON.stringify(state)) throw new Error('发送记录未确认保存，已停止发送。');
    }
    async saveImpl(noteId, draft, base) {
      id(noteId); content(draft); content(base);
      const current = await this.store.read(noteId);
      if (!same(current, base) && !same(current, draft)) {
        throw new Error('笔记已在其他编辑器变更。当前文字仍在此处，请复制后重新打开；不会覆盖已有修改。');
      }
      if (!same(current, draft)) await this.store.write(noteId, content(draft));
      const saved = await this.store.read(noteId);
      if (!same(saved, draft)) throw new Error('本地保存未确认。请保留编辑内容并重试。');
      return saved;
    }
    save(noteId, draft, base) { return this.run(() => this.saveImpl(noteId, draft, base)); }
    complete(noteId, draft, base) {
      return this.run(async () => {
        const saved = await this.saveImpl(noteId, draft, base);
        const state = journal(await this.store.readJournal(noteId), noteId);
        let record = state.records[state.records.length - 1];
        if (!record || !same(record.snapshot, saved)) {
          if (state.records.length >= 100) throw new Error('此笔记已有 100 个提交版本；请新建笔记，原记录会保留。');
          const version = state.records.length + 1;
          record = { version, key: noteId + ':' + version, snapshot: content(saved), state: 'pending', attempts: 0 };
          state.records.push(record);
          await this.writeJournal(noteId, state);
        }
        await this.deliver(noteId, state, record);
        return this.read(noteId);
      });
    }
    retry(noteId, version) {
      return this.run(async () => {
        await this.store.read(id(noteId));
        const state = journal(await this.store.readJournal(noteId), noteId);
        const record = state.records.find(r => r.version === version);
        if (!record) throw new Error('没有找到待重试版本。');
        await this.deliver(noteId, state, record);
        return this.read(noteId);
      });
    }
    async deliver(noteId, state, record) {
      if (record.state === 'accepted') return;
      if (this.adapter.connected !== true) {
        record.state = 'disconnected';
        record.error = '未连接：笔记和提交快照已保留，尚未上传。';
        await this.writeJournal(noteId, state);
        return;
      }
      record.state = 'sending';
      record.attempts++;
      delete record.error;
      await this.writeJournal(noteId, state);
      let timer;
      let receipt;
      try {
        receipt = await Promise.race([
          this.adapter.send(copy({ noteId, version: record.version, key: record.key, snapshot: record.snapshot })),
          new Promise((_, reject) => { timer = setTimeout(() => reject(new Error('timeout')), this.timeoutMs); })
        ]);
        if (!receipt || receipt.key !== record.key || receipt.status !== 'accepted' ||
            typeof receipt.receiptId !== 'string' || !receipt.receiptId || receipt.receiptId.length > 200) {
          throw new Error('invalid receipt');
        }
      } catch (_) {
        record.state = 'unknown';
        record.error = '服务接收结果未知；快照保留。重试会使用同一提交标识。';
      } finally { clearTimeout(timer); }
      if (receipt && receipt.key === record.key && receipt.status === 'accepted' &&
          typeof receipt.receiptId === 'string' && receipt.receiptId.length > 0 && receipt.receiptId.length <= 200) {
        record.state = 'accepted';
        record.receiptId = receipt.receiptId;
      }
      // A failure here leaves durable 'sending': read as uncertain, never as success.
      await this.writeJournal(noteId, state);
    }
  }
  return { Service, disconnected, content, id, journal, same, JOURNAL_KEY, MAX_BODY };
})();
if (typeof module !== 'undefined') module.exports = DotCore;

'use strict';
const DotStore = (() => {
  const marker = 'dotNotesNotebook.v1';
  class Store {
    constructor(joplin) { this.api = joplin; }
    async localOnly() {
      const [target] = await this.api.settings.globalValues(['sync.target']);
      if (target !== 0 && target !== '0') {
        throw new Error('请在未启用同步的 Joplin 配置中使用。当前配置无法确认仅本地保存，已停止写入。');
      }
    }
    async folder(create = false) {
      const walk = async items => {
        for (const item of items) {
          if (await this.api.data.userDataGet(2, item.id, marker) === true) return item.id;
          const child = await walk(item.children || []);
          if (child) return child;
        }
        return null;
      };
      for (let page = 1; ; page++) {
        const result = await this.api.data.get(['folders'], { fields: ['id'], limit: 100, page });
        const found = await walk(result.items || result);
        if (found) return found;
        if (!result.has_more) break;
      }
      if (!create) return null;
      await this.localOnly();
      const folder = await this.api.data.post(['folders'], null, { title: 'Dot Notes · 本地记事' });
      await this.api.data.userDataSet(2, folder.id, marker, true);
      return folder.id;
    }
    async list() {
      const folderId = await this.folder();
      if (!folderId) return [];
      const all = [];
      for (let page = 1; ; page++) {
        const result = await this.api.data.get(['folders', folderId, 'notes'], {
          fields: ['id', 'title', 'updated_time', 'deleted_time'], limit: 100, page,
          order_by: 'updated_time', order_dir: 'DESC'
        });
        all.push(...result.items.filter(n => !n.deleted_time));
        if (!result.has_more) return all;
      }
    }
    async create() {
      await this.localOnly();
      const parent_id = await this.folder(true);
      const note = await this.api.data.post(['notes'], null, { parent_id, title: '', body: '', markup_language: 1 });
      return this.read(note.id);
    }
    async read(noteId) {
      DotCore.id(noteId);
      const note = await this.api.data.get(['notes', noteId], {
        fields: ['id', 'title', 'body', 'parent_id', 'deleted_time', 'is_conflict', 'markup_language']
      });
      if (note.parent_id !== await this.folder() || note.deleted_time || note.is_conflict || note.markup_language !== 1) {
        throw new Error('此笔记不在本地记事本中，或已删除/存在冲突；不会修改。');
      }
      return note;
    }
    async write(noteId, draft) {
      await this.localOnly();
      await this.read(noteId);
      return this.api.data.put(['notes', noteId], null, { title: draft.title, body: draft.body });
    }
    async readJournal(noteId) {
      return this.api.data.userDataGet(1, noteId, DotCore.JOURNAL_KEY);
    }
    async writeJournal(noteId, state) {
      await this.localOnly();
      await this.read(noteId);
      return this.api.data.userDataSet(1, noteId, DotCore.JOURNAL_KEY, state);
    }
  }
  return { Store };
})();
if (typeof module !== 'undefined') module.exports = DotStore;

'use strict';
function createController(api, adapter) {
  const store = new DotStore.Store(api);
  const service = new DotCore.Service(store, adapter);
  return async message => {
    try {
      if (!message || typeof message !== 'object') throw new Error('请求格式无效。');
      let value;
      switch (message.type) {
        case 'list': value = await store.list(); break;
        case 'create': value = await service.run(async () => service.read((await store.create()).id)); break;
        case 'open': value = await service.run(() => service.read(message.id)); break;
        case 'save': value = await service.save(message.id, message.draft, message.base); break;
        case 'complete': value = await service.complete(message.id, message.draft, message.base); break;
        case 'retry': value = await service.retry(message.id, message.version); break;
        default: throw new Error('未知操作。');
      }
      return { ok: true, value };
    } catch (e) {
      // Never log note contents or raw backend errors.
      return { ok: false, error: /[\u4e00-\u9fff]/.test(e.message || '') ? e.message : '本地操作失败；请保留编辑内容后重试。' };
    }
  };
}
if (typeof module !== 'undefined') module.exports = { createController };

const PANEL_HTML = "<main id=\"app\">\n  <header><div><span class=\"eyebrow\">LOCAL NOTEBOOK</span><h1>记下，写完再交给 dot。</h1></div><button id=\"new\" class=\"primary\">＋ 新建笔记</button></header>\n  <div class=\"connection\"><span class=\"dot\"></span><strong>dot 未连接</strong><span>笔记只存本地。完成后也不会假装发送成功。</span></div>\n  <div id=\"error\" role=\"alert\" hidden></div>\n  <div class=\"workspace\">\n    <aside aria-label=\"笔记列表\"><div class=\"list-heading\"><span>我的笔记</span><span id=\"count\">0</span></div><div id=\"list\"></div></aside>\n    <section id=\"empty\"><div class=\"empty-symbol\">＋</div><h2>给一个想法留个位置。</h2><p>新建一条笔记，随时写下。<br>不需要账号，也不需要联网。</p></section>\n    <section id=\"editor\" hidden aria-label=\"编辑笔记\">\n      <label class=\"sr-only\" for=\"title\">标题</label><input id=\"title\" placeholder=\"无标题笔记\" maxlength=\"500\" autocomplete=\"off\">\n      <label class=\"sr-only\" for=\"body\">正文</label><textarea id=\"body\" placeholder=\"从这里开始写……\" maxlength=\"180000\" spellcheck=\"true\"></textarea>\n      <footer><span id=\"save-status\" role=\"status\" aria-live=\"polite\">本地已保存</span><button id=\"save\">保存 / 重试</button><button id=\"send\" class=\"primary\">完成并发送</button></footer>\n      <details id=\"history\"><summary>发送记录 <span id=\"history-count\">0</span></summary><p class=\"hint\">每条记录固定对应当时的标题和正文。服务接收不代表 dot 已处理。</p><div id=\"records\"></div></details>\n    </section>\n  </div>\n  <p class=\"bottom-note\">由 Joplin 本地存储支持 · 普通保存不会发送 · 未连接时保留提交快照</p>\n</main>\n";
/* global joplin, PANEL_HTML, createController */
joplin.plugins.register({
  onStart: async function () {
    const panels = joplin.views.panels;
    const panel = await panels.create('dotNotes');
    await panels.onMessage(panel, createController(joplin));
    await panels.setHtml(panel, PANEL_HTML);
    await panels.addScript(panel, './panel.css');
    await panels.addScript(panel, './panel.js');
    await joplin.commands.register({ name: 'dotNotesOpen', label: '打开本地记事', iconName: 'fas fa-pen', execute: async () => panels.show(panel) });
    await joplin.views.toolbarButtons.create('dotNotesOpenButton', 'dotNotesOpen', 'editorToolbar');
    await panels.show(panel);
  }
});

})();

